export interface StoreEntry<T> {
  value: T;
  version: number;
  expiresAt?: number;
}

export class VersionedStore<T> {
  private entries = new Map<string, StoreEntry<T>>();

  constructor(private initialVersion = 1) {}

  get(key: string): T | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt !== undefined && Date.now() > entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  set(key: string, value: T, ttlMs?: number): number {
    const previous = this.entries.get(key);
    const version = (previous?.version ?? this.initialVersion - 1) + 1;
    const expiresAt = ttlMs !== undefined ? Date.now() + ttlMs : undefined;
    this.entries.set(key, { value, version, expiresAt });
    return version;
  }

  versionOf(key: string): number | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt !== undefined && Date.now() > entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.version;
  }
}

